#[derive(Debug, Clone)]
pub struct Properties {
    map: BTreeMap<String, String>,
}

impl Properties {
    /// Loads the file; missing keys are filled with defaults and the file is saved (like vanilla).
    pub fn load_or_create(path: &Path) -> Result<Self> {
        let mut map: BTreeMap<String, String> = DEFAULTS.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect();
        let existed = path.exists();
        if existed {
            for line in std::fs::read_to_string(path)?.lines() {
                let line = line.trim_start();
                if line.is_empty() || line.starts_with('#') || line.starts_with('!') {
                    continue;
                }
                if let Some((k, v)) = line.split_once('=') {
                    map.insert(k.trim().to_owned(), unescape(v.trim_start()));
                }
            }
        }
        let p = Self { map };
        if !existed {
            p.save(path)?;
        }
        Ok(p)
    }

    pub fn save(&self, path: &Path) -> Result<()> {
        let mut out = String::from("#Minecraft server properties\n");
        out.push_str(&format!("#{}\n", chrono_like_now()));
        for (k, v) in &self.map {
            out.push_str(&format!("{}={}\n", k, escape(v)));
        }
        std::fs::write(path, out)?;
        Ok(())
    }

    pub fn str(&self, k: &str) -> &str {
        self.map.get(k).map(String::as_str).unwrap_or("")
    }
    pub fn int(&self, k: &str, default: i64) -> i64 {
        self.str(k).trim().parse().unwrap_or(default)
    }
    pub fn bool(&self, k: &str, default: bool) -> bool {
        match self.str(k).trim().to_ascii_lowercase().as_str() {
            "true" => true,
            "false" => false,
            _ => default,
        }
    }
}

/// `Properties.store` escapes `:` and `=` in values (e.g. `minecraft\:normal`).
fn escape(v: &str) -> String {
    v.replace('\\', "\\\\").replace(':', "\\:").replace('=', "\\=")
}
fn unescape(v: &str) -> String {
    let mut out = String::with_capacity(v.len());
    let mut it = v.chars();
    while let Some(c) = it.next() {
        if c == '\\' {
            if let Some(n) = it.next() {
                out.push(n);
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn chrono_like_now() -> String {
    // No chrono dependency: the date has no semantic meaning.
    let secs = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0);
    format!("unix-time {secs}")
}

/// Returns the configured settings in a convenient, typed form.
/// Some fields (world, seed) will be used by the world generator / Anvil loading.
#[allow(dead_code)]
#[derive(Debug, Clone)]
pub struct Settings {
    pub ip: String,
    pub port: u16,
    pub motd: String,
    pub max_players: i32,
    pub online_mode: bool,
    pub compression_threshold: i32,
    pub view_distance: i32,
    pub simulation_distance: i32,
    pub level_name: String,
    pub level_seed: String,
    pub level_type: String,
    pub game_mode: u8,
    pub difficulty: u8,
    pub hardcore: bool,
    pub enforce_secure_profile: bool,
    pub enable_status: bool,
    pub force_game_mode: bool,
    pub hide_online_players: bool,
}

impl Settings {
    pub fn from(p: &Properties) -> Self {
        let gm = match p.str("gamemode").trim().to_ascii_lowercase().as_str() {
            "creative" | "1" => 1,
            "adventure" | "2" => 2,
            "spectator" | "3" => 3,
            _ => 0,
        };
        let diff = match p.str("difficulty").trim().to_ascii_lowercase().as_str() {
            "peaceful" | "0" => 0,
            "easy" | "1" => 1,
            "hard" | "3" => 3,
            _ => 2, // normal
        };
        Self {
            ip: p.str("server-ip").to_owned(),
            port: p.int("server-port", 25565) as u16,
            motd: p.str("motd").to_owned(),
            max_players: p.int("max-players", 20) as i32,
            online_mode: p.bool("online-mode", true),
            compression_threshold: p.int("network-compression-threshold", 256) as i32,
            view_distance: (p.int("view-distance", 10) as i32).clamp(3, 32),
            simulation_distance: (p.int("simulation-distance", 10) as i32).clamp(3, 32),
            level_name: p.str("level-name").to_owned(),
            level_seed: p.str("level-seed").to_owned(),
            level_type: p.str("level-type").to_owned(),
            game_mode: gm,
            difficulty: diff,
            hardcore: p.bool("hardcore", false),
            enforce_secure_profile: p.bool("enforce-secure-profile", true),
            enable_status: p.bool("enable-status", true),
            force_game_mode: p.bool("force-gamemode", false),
            hide_online_players: p.bool("hide-online-players", false),
        }
    }
}

/// `WorldOptions.parseSeed`: empty -> random; an integer -> that number; otherwise `String.hashCode()`.
pub fn parse_seed(s: &str) -> i64 {
    let t = s.trim();
    if t.is_empty() {
        use rand::Rng;
        return rand::thread_rng().r#gen();
    }
    match t.parse::<i64>() {
        Ok(v) => v,
        Err(_) => java_string_hash(t) as i64,
    }
}

pub use mc_protocol::nbt::java_string_hash;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn seeds_like_java() {
        assert_eq!(parse_seed("12345"), 12345);
        assert_eq!(parse_seed("-9876543210"), -9876543210);
        // "hello".hashCode() == 99162322 w Javie
        assert_eq!(java_string_hash("hello"), 99162322);
        assert_eq!(parse_seed("hello"), 99162322);
    }

    #[test]
    fn default_level_type_is_stored_escaped_and_read_unescaped() {
        let dir = std::env::temp_dir().join(format!("mc-config-test-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("server.properties");
        let created = Properties::load_or_create(&path).unwrap();
        assert_eq!(created.str("level-type"), "minecraft:normal");
        // like Java's Properties.store: the colon is escaped in the file
        assert!(std::fs::read_to_string(&path).unwrap().contains("level-type=minecraft\\:normal"));
        let loaded = Properties::load_or_create(&path).unwrap();
        assert_eq!(Settings::from(&loaded).level_type, "minecraft:normal");
        let _ = std::fs::remove_dir_all(&dir);
    }
}
